      rowElement.innerHTML = `<div class="copywriting-brand-cell"><span class="material-symbols-outlined">storefront</span><div><strong>${row[0]}</strong><button type="button" aria-expanded="false" class="copy-row-expand-button"><span class="material-symbols-outlined">open_in_full</span><span>Expand row</span></button></div></div>${row[1].map(function (copy, index) { return `<article class="copywriting-copy-card rounded-xl"><div class="copywriting-card-top"><span class="copywriting-category">${categories[index]}</span></div><p class="copy-preview line-clamp-3">${copy}</p></article>`; }).join('')}`;
      body.appendChild(rowElement);
      if (row[0] === 'GlowHaus Beauty Studio') {
        const brandCell = rowElement.querySelector('.copywriting-brand-cell');
        if (brandCell) brandCell.insertAdjacentHTML('beforeend', `<div class="copywriting-brand-notes"><strong>TARGET AUDIENCE</strong><br><br><strong>Demographics:</strong> Content creators, young lifestyle vloggers, university students, and independent young adults ages 18–30.<br><br><strong>Psychographics:</strong> Highly influenced by TikTok, Instagram Reels, and Pinterest trends. They want anime bottom-lash extensions, custom builder-gel extensions, and viral nail art they can proudly show off in their next aesthetic video.<br><br><strong>Deep Pain Point:</strong> They fear an outdated salon experience that does not understand modern Gen Z styling trends or delivers thick, chunky, non-aesthetic finishes.<br><br><strong>Core Language Style:</strong> Natural Manila Taglish and casual English.</div>`);
      }
      if (row[0] === 'PrimeNest Realty') {
        const brandCell = rowElement.querySelector('.copywriting-brand-cell');
        if (brandCell) brandCell.insertAdjacentHTML('beforeend', `<div class="copywriting-brand-notes"><strong>TARGET AUDIENCE</strong><br><br><strong>Demographics:</strong> OFWs, sea-farers, healthcare workers abroad, and migrant workers ages 30–50.<br><br><strong>Psychographics:</strong> They work exhausting shifts away from home and sacrifice family time to provide a secure future. They see buying property as validation of their hard work and a safety net before retiring in the Philippines. They rely on virtual walkthroughs and online reviews because they cannot physically visit construction sites.<br><br><strong>Deep Pain Point:</strong> They fear getting scammed or locked into a 15-year financial obligation for a ghost project or substandard build. They dislike aggressive hard-sell tactics and hidden structural flaws such as poor drainage, thin partition walls, and low-quality concrete finishing.<br><br><strong>Core Language Style:</strong> Natural Manila Taglish and casual English.</div>`);
      }
      if (row[0] === 'Brew & Bloom Café') {
        const brandCell = rowElement.querySelector('.copywriting-brand-cell');
        if (brandCell) brandCell.insertAdjacentHTML('beforeend', `<div class="copywriting-brand-notes"><strong>TARGET AUDIENCE</strong><br><br><strong>Demographics:</strong> Upper-middle-class women, corporate professionals on weekends, and neighborhood “titas” ages 28–50.<br><br><strong>Psychographics:</strong> They treat coffee drinking as a sacred, non-negotiable self-care ritual or a peaceful catch-up session with close friends. They value quiet luxury, comfort, and premium quality, favoring artisanal coffee blends, fresh floral aromas, and a calming, green sanctuary vibe away from chaotic city noise. They appreciate attentive, polite customer service and high-quality ingredients.<br><br><strong>Deep Pain Point:</strong> They hate overcrowded, noisy cafés with long, chaotic lines and loud, echoey acoustics that ruin their peace of mind. They get frustrated with generic, mass-produced syrups and burned espresso shots that ruin their slow-morning experience.<br><br><strong>Core Language Style:</strong> Natural Manila Taglish and casual English.</div>`);
      }
      if (row[0] === 'LearnLab Academy') {
        const brandCell = rowElement.querySelector('.copywriting-brand-cell');
        if (brandCell) brandCell.insertAdjacentHTML('beforeend', `<div class="copywriting-brand-notes"><strong>TARGET AUDIENCE</strong><br><br><strong>Demographics:</strong> University students, fresh graduates, shy professionals, and young adults wanting to improve their social communication ages 16–28.<br><br><strong>Psychographics:</strong> They are academically smart and can write perfect English essays, but freeze when forced to speak in public or socialize in professional English settings. They see communication as a barrier to self-esteem and social mobility, overthinking their grammar and worrying that people will call them “feeling smart” or “maarte.” They seek a safe, supportive, and interactive environment where they can build conversational fluency without fear of embarrassment.<br><br><strong>Deep Pain Point:</strong> They hate hyper-critical, rigid learning environments where teachers call out every grammatical slip-up or laugh at wrong pronunciations. These experiences trigger their social anxiety and force them to stay silent during group discussions.<br><br><strong>Core Language Style:</strong> Natural Manila Taglish and casual English.</div>`);
      }
      if (row[0] === 'Soléa Fashion Co.') {
        const brandCell = rowElement.querySelector('.copywriting-brand-cell');
        if (brandCell) brandCell.insertAdjacentHTML('beforeend', `<div class="copywriting-brand-notes"><strong>TARGET AUDIENCE</strong><br><br><strong>Demographics:</strong> Young corporate professionals, creative directors, tech earners, and modern working women ages 23–35.<br><br><strong>Psychographics:</strong> They subscribe to the “less is more” philosophy and look for timeless, sustainable fashion pieces that offer an effortlessly chic look. They treat dressing up as a form of self-respect and identity, favoring neutral color palettes, linen fabrics, and high-quality tailoring. They prefer versatile premium essentials that transition easily from a high-stakes board meeting to a casual Friday weekend brunch.<br><br><strong>Deep Pain Point:</strong> They despise fast-fashion brands that look sleek in online catalog photos but use cheap, thin polyester blends that lose their shape, shrink, or fray after just one machine wash, forcing them to throw out clothes and waste money.<br><br><strong>Core Language Style:</strong> Natural Manila Taglish and casual English.</div>`);
      }
    });
    document.addEventListener('click', function (event) {
      const button = event.target.closest('.copy-row-expand-button');
      if (!button) return;
      event.stopPropagation();
      const row = button.closest('.copywriting-row');
      if (!row) return;
      const wasExpanded = row.classList.contains('copy-row-expanded');
      document.querySelectorAll('.copywriting-row.copy-row-expanded').forEach(function (otherRow) {
        otherRow.classList.remove('copy-row-expanded');
        otherRow.querySelectorAll('.copywriting-copy-card').forEach(function (card) {
          card.classList.remove('copy-card-expanded');
          const preview = card.querySelector('.copy-preview');
          if (preview) preview.classList.add('line-clamp-3');
        });
        const otherButton = otherRow.querySelector('.copy-row-expand-button');
        if (otherButton) {
          otherButton.setAttribute('aria-expanded', 'false');
          otherButton.querySelector('.material-symbols-outlined').textContent = 'open_in_full';
          otherButton.querySelector('span:last-child').textContent = 'Expand row';
        }
      });
      if (wasExpanded) return;
      row.classList.add('copy-row-expanded');
      row.querySelectorAll('.copywriting-copy-card').forEach(function (card) {
        card.classList.add('copy-card-expanded');
        const preview = card.querySelector('.copy-preview');
        if (preview) preview.classList.remove('line-clamp-3');
      });
      button.setAttribute('aria-expanded', 'true');
      button.querySelector('.material-symbols-outlined').textContent = 'close_fullscreen';
      button.querySelector('span:last-child').textContent = 'Minimize row';
    });
    document.addEventListener('click', function (event) {
      const card = event.target.closest('.copywriting-copy-card');
      if (!card || event.target.closest('button')) return;
      const row = card.closest('.copywriting-row');
      const rowButton = row ? row.querySelector('.copy-row-expand-button') : null;
      if (rowButton) rowButton.click();
    });
    document.querySelectorAll('.copywriting-copy-card .copy-expand-button').forEach(function (button) {
      button.__copyBound = true;
      button.addEventListener('click', function (event) {
        event.stopPropagation();
        const card = button.parentElement ? button.parentElement.parentElement : null;
        if (!card) return;
        const preview = card.querySelector('.copy-preview');
        const expanded = card.classList.toggle('copy-card-expanded');
        preview.classList.toggle('line-clamp-3', !expanded);
        button.querySelector('.material-symbols-outlined').textContent = expanded ? 'close_fullscreen' : 'open_in_full';
        button.querySelector('span:last-child').textContent = expanded ? 'Minimize' : 'Expand';
        button.setAttribute('aria-expanded', String(expanded));
      });
    });
    document.addEventListener('click', function (event) {
      const button = event.target.closest('.copywriting-copy-card .copy-expand-button');
      if (!button || button.__copyBound) return;
      event.stopPropagation();
      const card = button.parentElement ? button.parentElement.parentElement : null;
      if (!card) return;
      const preview = card.querySelector('.copy-preview');
      const expanded = card.classList.toggle('copy-card-expanded');
      preview.classList.toggle('line-clamp-3', !expanded);
      button.querySelector('.material-symbols-outlined').textContent = expanded ? 'close_fullscreen' : 'open_in_full';
      button.querySelector('span:last-child').textContent = expanded ? 'Minimize' : 'Expand';
      button.setAttribute('aria-expanded', String(expanded));
    });
    const copywritingStyle = document.createElement('style');
    copywritingStyle.textContent = `.copywriting-table-scroll{overflow-x:auto;padding-bottom:.35rem}.copywriting-table{min-width:68rem}.copywriting-header,.copywriting-row{display:grid;grid-template-columns:minmax(11rem,1.15fr) repeat(4,minmax(13rem,1fr));gap:.75rem}.copywriting-header{margin-bottom:.75rem}.copywriting-header-cell{padding:.7rem .85rem;color:#9a4023;font-size:.68rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.copywriting-body{display:grid;gap:.75rem}.copywriting-row{align-items:stretch}.copywriting-brand-cell,.copywriting-copy-card{border:1px solid rgba(154,64,35,.16);border-radius:.8rem;background:#f7eee9;padding:.9rem}.copywriting-brand-cell{display:flex;align-items:flex-start;gap:.55rem;color:#9a4023;font-size:.85rem;line-height:1.35}.copywriting-brand-cell .material-symbols-outlined{font-size:1.15rem}.copywriting-copy-card{min-height:11rem;transition:box-shadow .2s ease,transform .2s ease}.copywriting-copy-card:hover{box-shadow:0 8px 20px rgba(75,45,35,.1);transform:translateY(-1px)}.copywriting-card-top{display:flex;align-items:flex-start;justify-content:space-between;gap:.5rem}.copywriting-category{color:#9a4023;font-size:.64rem;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.copywriting-copy-card .copy-preview{margin:.8rem 0 0;color:#654e46;font-size:.78rem;line-height:1.55}.copywriting-copy-card.copy-card-expanded{box-shadow:0 12px 26px rgba(75,45,35,.16);transform:translateY(-2px)}.copywriting-copy-card.copy-card-expanded .copy-preview{max-height:none}.copywriting-copy-card .copy-expand-button{display:inline-flex;align-items:center;gap:.25rem;border:0;border-radius:.35rem;background:#eadfda;color:#9a4023;padding:.3rem .45rem;font-size:.62rem;font-weight:800;letter-spacing:.04em;text-transform:uppercase;cursor:pointer}.copywriting-copy-card .copy-expand-button:hover{background:#9a4023;color:#fff}.copywriting-copy-card .copy-expand-button .material-symbols-outlined{font-size:.9rem}`;
    document.head.appendChild(copywritingStyle);
    const brandNotesStyle = document.createElement('style');
    brandNotesStyle.textContent = `.copywriting-brand-cell{display:flex;flex-direction:column;align-items:center;text-align:center}.copywriting-brand-notes{display:none;margin-top:.9rem;color:#654e46;font-size:.68rem;line-height:1.55;text-align:center}.copywriting-row.copy-row-expanded .copywriting-brand-notes{display:block}.copywriting-brand-notes strong{color:#9a4023;font-size:.62rem;letter-spacing:.06em;text-transform:uppercase}.copywriting-brand-cell>div{width:100%}.copywriting-brand-cell>div>strong{display:block}.copy-row-expand-button{display:inline-flex;align-items:center;gap:.25rem;margin:.8rem auto 0;border:0;border-radius:.35rem;background:#eadfda;color:#9a4023;padding:.35rem .5rem;font-size:.62rem;font-weight:800;letter-spacing:.04em;text-transform:uppercase;cursor:pointer}.copy-row-expand-button:hover{background:#9a4023;color:#fff}.copy-row-expand-button .material-symbols-outlined{font-size:.9rem}`;
    document.head.appendChild(brandNotesStyle);
  }
}
